:root{font-family:Inter,system-ui,sans-serif;color:#20344f;background:#f5f8fc}*{box-sizing:border-box}
body{margin:0;background:#f5f8fc;color:#20344f;font:16px/1.55 Inter,system-ui,sans-serif}
