/* Atlas v3 shared wayfinding. Existing lab styles and IDs are preserved. */
.an{overflow-y:auto}.an nav{display:flex;flex-direction:column;gap:4px}
.an .atlas-nav-label{font-size:11px;letter-spacing:.1em;color:#8ea5c3;margin:18px 15px 6px;font-weight:800}
.an .atlas-nav-link{display:block;padding:10px 14px;min-height:44px;border-radius:10px;text-decoration:none}
