.an .atlas-nav-sub{font-size:13px;margin-left:12px;padding:7px 12px}
.an-top{display:flex;align-items:center;justify-content:space-between;gap:14px}
.an-top .atlas-top-links{display:flex;gap:16px;align-items:center;font-size:13px}
.an-top .atlas-top-links a{text-decoration:none}
.an-btm a{min-width:0;flex:1;text-align:center}.an-btm b{font-size:11px}
.an-btm .active{font-weight:800}
.atlas-route{border:1px solid #ccd9ea;background:#f4f8ff;border-radius:16px;padding:20px;margin:20px 0;color:#193455}
.atlas-route h2{font-size:22px;margin:0 0 8px}.atlas-route p{margin:0 0 12px;line-height:1.6}
.atlas-route-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}
.atlas-route-grid a,.atlas-button{display:block;border:1px solid #b7cbea;border-radius:9px;background:white;color:#16418f;padding:11px 14px;text-decoration:none;min-height:44px;font-weight:700}
.atlas-route-grid a:hover,.atlas-button:hover{background:#eaf2ff}
.atlas-lesson{border:1px solid #d2deef;background:#f6f9ff;border-radius:14px;padding:18px;margin:20px 0}
.atlas-lesson h2{margin:0 0 8px}.atlas-lesson p{line-height:1.65}
.atlas-lesson textarea{display:block;width:100%;min-height:100px;border:1px solid #9cb2d2;border-radius:8px;padding:12px;font:inherit}
.atlas-lesson button{min-height:44px;margin:10px 0;padding:9px 14px;border:1px solid #2362ba;border-radius:8px;background:#1454ad;color:white;font:inherit;cursor:pointer}
.atlas-lesson .atlas-feedback{min-height:1.5em;color:#174b82}
.atlas-source-details{margin:22px 0}.atlas-source-details>summary{font-weight:800;cursor:pointer;padding:14px;background:#eef3fb;border-radius:9px}
.atlas-source-details[open]>summary{margin-bottom:12px}
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #d07710;outline-offset:3px}
@media(max-width:700px){.an-top .atlas-top-links{display:none}.atlas-route{padding:15px}.an-btm{display:flex}.an-btm a{padding:8px 2px}.an-btm b{font-size:10px}}
