      if (!persistent) return false;
      try { storage.setItem(KEY, JSON.stringify(state)); return true; }
      catch (_) { persistent = false; warnings.push('Progress is in memory only'); return false; }
    }
    function migrate() {
      const stamp = now();
      if (!validTime(stamp)) throw new Error('Invalid clock');
      let changed = !state.legacyMigration;
