        old[name] = storage ? readJson(storage, key, warnings) : null;
      for (const id of sets.modules) {
        if (old.modules && old.modules[id] === true && !own(state.read, 'sql-' + id))
          { state.read['sql-' + id] = {markedAt: stamp, selfReported: true}; changed = true; }
      }
      const take = (record, kind, allowed, attempted, completed) => {
        for (const [id, value] of Object.entries(record || {})) {
          if (!allowed.has(id) || !isObject(value) || (!attempted(value) && !completed(value))) continue;
          const key = kind + ':' + id;
          if (!own(state.attempts, key)) {
            state.attempts[key] = {attemptCount: attempted(value) ? 1 : 0,
              completed: completed(value), lastCorrect: null, updatedAt: stamp};
            changed = true;
          } else if (completed(value) && !state.attempts[key].completed) {
            state.attempts[key].completed = true;
            state.attempts[key].updatedAt = stamp;
            changed = true;
          }
        }
      };
      take(old.guided, 'guided', sets.guided, v => v.answered === true, v => v.done === true);
      take(old.questions, 'question', sets.questions, v => v.answered === true, v => v.done === true);
      take(old.labs, 'lab', sets.labs, v => v.touched === true, v => v.touched === true);
      const items = isObject(old.senior?.items) ? old.senior.items : {};
      for (const [id, value] of Object.entries(items)) {
        if (sets.senior.has(id) && isObject(value) &&
            ['review', 'complete'].includes(value.status) &&
            (!own(state.senior, id) ||
             (value.status === 'complete' && state.senior[id].status !== 'complete'))) {
          state.senior[id] = {status: value.status, updatedAt: stamp};
